{"content": """"Generate the lyrics of 'I Know an Old Lady Who Swallowed a Fly'."""

_ANIMALS = ["fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"]

_COMMENTS = {
    1: "I don't know why she swallowed the fly. Perhaps she'll die.",
    2: "It wriggled and jiggled and tickled inside her.",
    3: "How absurd to swallow a bird!",
    4: "Imagine that, to swallow a cat!",
    5: "What a hog, to swallow a dog!",
    6: "Just opened her throat and swallowed a goat!",
    7: "I don't know how she swallowed a cow!",
    8: "She's dead, of course!",
}

_SPIDER_TAIL = " that wriggled and jiggled and tickled inside her"


def _verse(verse):
    animal = _ANIMALS[verse - 1]
    lines = [
        f"I know an old lady who swallowed a {animal}.",
        _COMMENTS[verse],
    ]
    if verse == 8:
        return lines

    for caught in reversed(_ANIMALS[: verse - 1]):
        tail = _SPIDER_TAIL if caught == "spider" else ""
        lines.append(
            f"She swallowed the {animal} to catch the {caught}{tail}."
        )
        animal = caught
    return lines


def recite(start_verse, end_verse):
    lines = []
    for verse in range(start_verse, end_verse + 1):
        if lines:
            lines.append("")
        lines.extend(_verse(verse))
    return lines
